/** Названия и описания мест на zh, ko, de, fr, ja, tr, ar. */
export const ЯЗЫКИ_КАШКАДАРЬИ: ЯзыкиРегиона = {
  "kd-oqsaroy": {
    zh: { name: "白宫（阿克萨莱）遗址", desc: "阿米尔·帖木儿在其故乡碣石（今沙赫里萨布兹）所建“白宫”的遗址。工程始于1380年，持续了二十多年：同时代人描述宫墙饰以黄金和青金石，庭院铺着白石，屋顶上还有一座水池。1404年见过这座宫殿的西班牙使节克拉维约写道，工匠们为它劳作了多年。如今只剩下入口门楼的巨大塔柱，高近40米——即使是废墟，其规模和精美的马赛克也令人惊叹。沙赫里萨布兹历史中心是联合国教科文组织世界遗产。" },
    ko: { name: "악사로이 궁전", desc: "아미르 티무르의 고향 케시, 지금의 샤흐리사브즈에 있는 ‘하얀 궁전’의 유적입니다. 1380년에 착공해 20년 넘게 공사가 이어졌으며, 당대 사람들은 금과 청금석으로 장식한 벽, 흰 돌을 깐 안뜰, 지붕 위의 연못을 기록했습니다. 1404년 궁전을 본 스페인 사절 클라비호는 장인들이 수년째 일하고 있다고 적었습니다. 지금은 높이 40m에 가까운 입구 정문의 거대한 기둥만 남았지만, 폐허임에도 그 규모와 정교한 모자이크가 놀랍습니다. 샤흐리사브즈 역사 지구는 유네스코 세계유산입니다." },
    de: { name: "Palast Ak-Saray", desc: "Die Ruinen von Amir Timurs „Weißem Palast“ in seiner Heimatstadt Kesch, dem heutigen Schahrisabs. Der Bau begann 1380 und dauerte mehr als zwanzig Jahre: Zeitgenossen beschrieben Wände mit Gold und Lapislazuli, mit weißem Stein gepflasterte Höfe und ein Becken auf dem Dach. Der spanische Gesandte Clavijo, der den Palast 1404 sah, schrieb, dass Handwerker seit Jahren daran arbeiteten. Erhalten sind nur die riesigen Pylonen des Eingangsportals, fast 40 Meter hoch – selbst als Ruine beeindrucken sie durch Größe und feines Mosaik. Das historische Zentrum von Schahrisabs ist UNESCO-Welterbe." },
    fr: { name: "Palais Ak-Saraï", desc: "Les ruines du « Palais blanc » d'Amir Timour dans sa ville natale de Kech, l'actuelle Chakhrisabz. La construction commença en 1380 et dura plus de vingt ans : les contemporains décrivent des murs ornés d'or et d'azur, des cours pavées de pierre blanche et un bassin sur le toit. L'ambassadeur espagnol Clavijo, qui vit le palais en 1404, écrivit que des artisans y travaillaient depuis des années. Seuls subsistent les immenses pylônes du portail d'entrée, hauts de près de 40 mètres – même en ruine, ils étonnent par leur échelle et leur fine mosaïque. Le centre historique de Chakhrisabz est inscrit au patrimoine mondial de l'UNESCO." },
    ja: { name: "アク・サライ宮殿", desc: "アミール・ティムールの故郷ケシュ、現在のシャフリサブズにある「白い宮殿」の遺跡です。建設は1380年に始まり20年以上続きました。同時代の人々は、金と瑠璃で飾られた壁、白い石を敷いた中庭、屋上の池について記しています。1404年に宮殿を見たスペインの使節クラビホは、職人たちが何年もかけて働いていると書きました。残るのは高さ40m近い入口門の巨大な塔柱だけですが、廃墟になってもその規模と精緻なモザイクには驚かされます。シャフリサブズ歴史地区はユネスコ世界遺産です。" },
    tr: { name: "Ak Saray", desc: "Emir Timur'un doğduğu kent Keş'te, bugünkü Şehrisebz'deki “Beyaz Saray”ın kalıntıları. İnşaat 1380'de başladı ve yirmi yıldan fazla sürdü: çağdaşları altın ve lacivertle süslü duvarları, beyaz taşla döşeli avluları ve damdaki havuzu anlatır. Sarayı 1404'te gören İspanyol elçi Clavijo, ustaların yıllardır onun üzerinde çalıştığını yazdı. Yalnızca giriş taç kapısının yaklaşık 40 metrelik dev ayakları ayakta kaldı – harabe halinde bile ölçekleri ve ince mozaikleriyle şaşırtır. Şehrisebz Tarihi Merkezi UNESCO Dünya Mirası'dır." },
    ar: { name: "قصر آق سراي", desc: "أطلال «القصر الأبيض» لأمير تيمور في مدينته الأم كش، شهرسبز اليوم. بدأ البناء عام 1380 واستمر أكثر من عشرين عامًا: وصف المعاصرون جدرانًا مزينة بالذهب واللازورد، وأفنية مرصوفة بالحجر الأبيض، وحوضًا على السطح. وكتب السفير الإسباني كلافيخو، الذي رأى القصر عام 1404، أن الحرفيين ظلوا يعملون فيه سنوات. لم يبقَ إلا الركائز الضخمة لبوابة المدخل بارتفاع يقارب 40 مترًا – ولا تزال حتى وهي أطلال تدهش بحجمها وفسيفسائها الدقيقة. والمركز التاريخي لشهرسبز مدرج في قائمة التراث العالمي لليونسكو." },
  },
  "kd-temurstatue": {
    zh: { name: "沙赫里萨布兹的阿米尔·帖木儿雕像", desc: "白宫门楼前的阿米尔·帖木儿全身青铜像，这座城市正是这位伟大征服者1336年的出生地。雕像于1996年为纪念帖木儿诞辰660周年而竖立，此后雕像与宫殿遗址之间的广场就成了沙赫里萨布兹的中心：游客和新人在这里合影，四周是有林荫道和喷泉的公园。从雕像出发沿着笔直的步行轴线，可以走到乔尔苏以及多鲁特·蒂洛瓦特和多鲁斯·萨奥达特建筑群。" },
    ko: { name: "샤흐리사브즈의 아미르 티무르 동상", desc: "위대한 정복자가 1336년에 태어난 도시, 악사로이 정문 앞에 선 아미르 티무르의 전신 청동상입니다. 티무르 탄생 660주년을 맞아 1996년에 세워졌으며, 이후 동상과 궁전 유적 사이의 광장은 샤흐리사브즈의 중심이 되었습니다. 관광객과 신혼부부가 사진을 찍고, 주변에는 가로수길과 분수가 있는 공원이 있습니다. 동상에서 곧게 뻗은 보행로를 따라 초르수와 도루트 틸로바트, 도루스 사오다트 단지로 갈 수 있습니다." },
    de: { name: "Amir-Timur-Denkmal in Schahrisabs", desc: "Eine lebensgroße Bronzestatue Amir Timurs vor dem Portal von Ak-Saray, in der Stadt, in der der große Eroberer 1336 geboren wurde. Sie wurde 1996 zu Timurs 660. Geburtstag errichtet, und der Platz zwischen Statue und Palastruinen ist seitdem das Herz von Schahrisabs: Touristen und Brautpaare fotografieren sich hier, ringsum liegt ein Park mit Alleen und Springbrunnen. Eine gerade Fußgängerachse führt von der Statue zum Chorsu und zu den Ensembles Dorut Tilovat und Dorus Saodat." },
    fr: { name: "Monument d'Amir Timour à Chakhrisabz", desc: "Une statue de bronze en pied d'Amir Timour devant le portail d'Ak-Saraï, dans la ville où le grand conquérant naquit en 1336. Elle fut érigée en 1996 pour le 660e anniversaire de Timour, et la place entre la statue et les ruines du palais est depuis le cœur de Chakhrisabz : touristes et jeunes mariés y posent pour des photos, entourés d'un parc aux allées et fontaines. Un axe piéton rectiligne mène de la statue au Tchorsou et aux ensembles Dorout Tilovat et Dorous Saodat." },
    ja: { name: "シャフリサブズのアミール・ティムール像", desc: "偉大な征服者が1336年に生まれた町で、アク・サライの門の前に立つアミール・ティムールの全身のブロンズ像です。ティムール生誕660年を記念して1996年に建てられ、以来、像と宮殿跡の間の広場はシャフリサブズの中心となりました。観光客や新婚カップルが記念撮影をし、周囲には並木道と噴水のある公園があります。像からまっすぐな歩行者軸をたどると、チョルスーやドルト・ティロヴァト、ドルス・サオダトの建築群へ行けます。" },
    tr: { name: "Şehrisebz'deki Emir Timur Anıtı", desc: "Büyük fatihin 1336'da doğduğu şehirde, Ak Saray'ın taç kapısı önünde Emir Timur'un ayakta bronz heykeli. 1996'da Timur'un doğumunun 660. yıldönümü için dikildi; o zamandan beri heykel ile saray kalıntıları arasındaki meydan Şehrisebz'in kalbidir: turistler ve yeni evliler burada fotoğraf çektirir, çevresinde ağaçlı yollar ve fıskiyelerle bir park vardır. Heykelden düz bir yaya aksı Çarsu'ya ve Dorut Tilavet ile Dorus Saadet külliyelerine uzanır." },
    ar: { name: "تمثال أمير تيمور في شهرسبز", desc: "تمثال برونزي كامل لأمير تيمور أمام بوابة آق سراي، في المدينة التي وُلد فيها الفاتح العظيم عام 1336. أُقيم عام 1996 بمناسبة الذكرى الـ660 لميلاد تيمور، ومنذ ذلك الحين صارت الساحة بين التمثال وأطلال القصر قلب شهرسبز: يلتقط فيها السياح والعرسان الصور، وحولها حديقة بممرات ونوافير. ويقود محور مشاة مستقيم من التمثال إلى «تشورسو» ومجمعي دار التلاوة ودار السيادة." },
  },
  "kd-dorut": {
    zh: { name: "多鲁特·蒂洛瓦特建筑群", desc: "沙赫里萨布兹南部14世纪末至15世纪的纪念建筑群，名字意为“诵经之所”。其核心是谢赫沙姆西丁·库洛尔的陵墓，他是帖木儿父亲及少年帖木儿的精神导师。对面是兀鲁伯1435年为纪念父亲沙哈鲁而建的库克·古姆巴兹清真寺，附近是同样建于兀鲁伯时期、安葬先知后裔的贡巴济·赛义丹陵墓。这是礼拜场所：请穿着得体，女士应包头巾。" },
    ko: { name: "도루트 틸로바트 단지", desc: "샤흐리사브즈 남쪽에 있는 14세기 말~15세기의 기념 단지로, 이름은 쿠란을 낭송하는 곳, ‘묵상의 집’이라는 뜻입니다. 중심에는 티무르의 아버지와 어린 티무르의 영적 스승이었던 셰이흐 샴시딘 쿨롤의 영묘가 있습니다. 맞은편에는 울루그베크가 1435년 아버지 샤루흐를 기려 세운 쿡 굼바즈 모스크가, 가까이에는 역시 울루그베크 시대에 지은 예언자 후손들의 묘 굼바지 사이돈 영묘가 있습니다. 예배 장소이니 단정하게 입고 여성은 머리를 가리세요." },
    de: { name: "Ensemble Dorut Tilovat", desc: "Ein Gedenkensemble des späten 14. und 15. Jahrhunderts im Süden von Schahrisabs; der Name bedeutet „Haus der Besinnung“, ein Ort der Koranrezitation. Im Zentrum steht das Mausoleum von Scheich Schamsiddin Kulol, dem geistigen Lehrer von Timurs Vater und des jungen Timur selbst. Gegenüber steht die Kok-Gumbaz-Moschee, die Ulugh Beg 1435 zu Ehren seines Vaters Schah Ruch erbaute, und nahebei das Mausoleum Gumbazi Sayidon, Grab der Nachkommen des Propheten, ebenfalls unter Ulugh Beg errichtet. Ein Ort des Gebets: zurückhaltend kleiden, Frauen bedecken das Haar." },
    fr: { name: "Ensemble Dorout Tilovat", desc: "Un ensemble mémorial de la fin du XIVe et du XVe siècle au sud de Chakhrisabz ; son nom signifie « maison de la méditation », lieu de récitation du Coran. Au cœur, le mausolée du cheikh Chamsiddin Koulol, maître spirituel du père de Timour et du jeune Timour lui-même. En face se dresse la mosquée Kok Goumbaz, bâtie par Ouloug Beg en 1435 en l'honneur de son père Chah Rokh, et tout près le mausolée Goumbazi Saïdon, tombeau des descendants du Prophète, élevé lui aussi sous Ouloug Beg. Lieu de culte : tenue correcte, cheveux couverts pour les femmes." },
    ja: { name: "ドルト・ティロヴァト建築群", desc: "シャフリサブズ南部にある14世紀末～15世紀の記念建築群で、名前はコーランを読誦する場所「瞑想の家」を意味します。中心にはティムールの父と若きティムールの霊的な師であったシェイフ・シャムスィッディン・クロルの霊廟があります。向かいにはウルグベクが1435年に父シャー・ルフをたたえて建てたコク・グンバズ・モスク、近くには同じくウルグベクの時代に建てられた預言者の子孫の墓、グンバズィ・サイードン廟があります。礼拝の場なので、控えめな服装で、女性は髪を覆ってください。" },
    tr: { name: "Dorut Tilavet Külliyesi", desc: "Şehrisebz'in güneyinde 14. yüzyıl sonu ve 15. yüzyıldan bir anıt külliye; adı Kur'an okunan yer, “Tefekkür Evi” demektir. Merkezinde Timur'un babasının ve genç Timur'un manevi hocası Şeyh Şemseddin Külal'ın türbesi bulunur. Karşısında Uluğ Bey'in 1435'te babası Şahruh onuruna yaptırdığı Gök Kubbe Camii, yakınında da yine Uluğ Bey döneminde yapılan, Peygamber soyundan gelenlerin türbesi Kubbe-i Seyyidan durur. Bir ibadet yeridir: kapalı giyinin, kadınlar başını örtsün." },
    ar: { name: "مجمع دار التلاوة", desc: "مجمع تذكاري من أواخر القرن الرابع عشر والقرن الخامس عشر جنوب شهرسبز، ويعني اسمه «دار التلاوة» أي مكان قراءة القرآن. في قلبه ضريح الشيخ شمس الدين كلال، المعلم الروحي لوالد تيمور ولتيمور في صباه. وقبالته مسجد «كوك غومباز» الذي بناه أولوغ بيك عام 1435 تكريمًا لوالده شاهرخ، وبالقرب منه ضريح «قبة السادات» مدفن ذرية النبي، الذي بُني أيضًا في عهد أولوغ بيك. مكان عبادة: ارتدِ ملابس محتشمة، وعلى النساء تغطية الشعر." },
  },
  "kd-kokgumbaz": {
    zh: { name: "沙赫里萨布兹的库克·古姆巴兹清真寺", desc: "兀鲁伯于1434–1435年为纪念父亲沙哈鲁而建的聚礼清真寺，是多鲁特·蒂洛瓦特建筑群的主体建筑。名字意为“蓝色穹顶”：高鼓座上的巨大穹顶曾贴满绿松石色瓷砖，远远就能看见。门楼上保存着带有帖木儿家族成员名字和建造年代的历史铭文，内部绘有蓝金色图案。这是正在使用的清真寺：请在礼拜时间以外参观，并穿着得体。" },
    ko: { name: "샤흐리사브즈의 쿡 굼바즈 모스크", desc: "울루그베크가 1434~1435년 아버지 샤루흐를 기려 세운 금요 모스크로, 도루트 틸로바트 단지의 중심 건물입니다. 이름은 ‘푸른 돔’이라는 뜻으로, 높은 드럼 위의 거대한 돔은 청록색 타일로 덮여 멀리서도 보였습니다. 정문에는 티무르 가문 사람들의 이름과 건립 연도를 적은 역사적 명문이 남아 있고, 실내는 파란색과 금색 문양으로 칠해져 있습니다. 현재 예배하는 모스크이니 예배 시간을 피해 단정하게 방문하세요." },
    de: { name: "Kok-Gumbaz-Moschee in Schahrisabs", desc: "Eine Freitagsmoschee, die Ulugh Beg 1434–1435 zu Ehren seines Vaters Schah Ruch erbaute; sie ist der Hauptbau des Ensembles Dorut Tilovat. Der Name bedeutet „Blaue Kuppel“: Die riesige Kuppel auf hohem Tambour war mit türkisfarbenen Fliesen verkleidet und weithin sichtbar. Am Portal sind historische Inschriften mit den Namen der Timuriden und dem Baujahr erhalten, das Innere ist mit blauen und goldenen Mustern bemalt. Eine aktive Moschee: außerhalb der Gebetszeiten und zurückhaltend gekleidet besuchen." },
    fr: { name: "Mosquée Kok Goumbaz de Chakhrisabz", desc: "Une mosquée du vendredi bâtie par Ouloug Beg en 1434–1435 en l'honneur de son père Chah Rokh ; c'est l'édifice principal de l'ensemble Dorout Tilovat. Son nom signifie « coupole bleue » : l'immense coupole sur un haut tambour était revêtue de carreaux turquoise et se voyait de loin. Des inscriptions historiques portant les noms des Timourides et la date de construction subsistent sur le portail, et l'intérieur est peint de motifs bleus et or. Mosquée active : visitez en dehors des heures de prière, en tenue correcte." },
    ja: { name: "シャフリサブズのコク・グンバズ・モスク", desc: "ウルグベクが1434～1435年に父シャー・ルフをたたえて建てた金曜モスクで、ドルト・ティロヴァト建築群の中心となる建物です。名前は「青いドーム」を意味し、高いドラム部の上の巨大なドームはターコイズのタイルで覆われ、遠くからも見えました。門にはティムール家の人々の名と建設年を記した歴史的な銘文が残り、内部は青と金の文様で彩られています。現役のモスクなので、礼拝時間外に控えめな服装で訪れてください。" },
    tr: { name: "Şehrisebz'deki Gök Kubbe Camii", desc: "Uluğ Bey'in 1434–1435'te babası Şahruh onuruna yaptırdığı Cuma camii; Dorut Tilavet külliyesinin ana yapısıdır. Adı “Mavi Kubbe” demektir: yüksek kasnaklı dev kubbe turkuaz çinilerle kaplıydı ve uzaktan görünürdü. Taç kapıda Timurluların adları ve inşa tarihiyle tarihi yazıtlar korunmuştur; içi mavi ve altın desenlerle boyalıdır. Faal bir camidir: namaz vakitleri dışında ve kapalı giyinerek ziyaret edin." },
    ar: { name: "مسجد كوك غومباز في شهرسبز", desc: "مسجد جامع بناه أولوغ بيك بين 1434 و1435 تكريمًا لوالده شاهرخ، وهو المبنى الرئيسي في مجمع دار التلاوة. يعني اسمه «القبة الزرقاء»: كانت القبة الضخمة على رقبتها العالية مكسوة ببلاط فيروزي وتُرى من بعيد. وعلى البوابة نقوش تاريخية بأسماء التيموريين وتاريخ البناء، والداخل مزدان بزخارف زرقاء وذهبية. مسجد قائم: زُره خارج أوقات الصلاة وبملابس محتشمة." },
  },
  "kd-dorussaodat": {
    zh: { name: "多鲁斯·萨奥达特与贾汉吉尔陵墓", desc: "阿米尔·帖木儿在故乡修建的家族陵墓，名字意为“权力与威严之所”。他早逝于1376年的长子、也是最宠爱的儿子贾汉吉尔的高大陵墓保存了下来，有独特的圆锥形穹顶。1943年，考古学家在附近发现了一座地下墓室，里面有帖木儿为自己准备的石棺——但他最终葬在撒马尔罕的古尔·埃米尔陵。旁边是哈兹拉提·伊玛目清真寺和有百年梧桐树荫的庭院。" },
    ko: { name: "도루스 사오다트와 자항기르 영묘", desc: "아미르 티무르가 고향에 지은 가족 묘로, 이름은 ‘권력과 위엄의 자리’라는 뜻입니다. 1376년 아주 젊은 나이에 세상을 떠난 그의 맏아들이자 가장 아끼던 아들 자항기르의 높은 영묘가 독특한 원뿔형 돔과 함께 남아 있습니다. 1943년 근처에서 고고학자들이 티무르가 자신을 위해 준비한 석관이 있는 지하 묘실을 발견했지만, 그는 사마르칸트의 구르 아미르에 묻혔습니다. 옆에는 하즈라티 이맘 모스크와 수백 년 된 플라타너스 그늘의 안뜰이 있습니다." },
    de: { name: "Dorus Saodat und Mausoleum Dschahongir", desc: "Die Familiengrabstätte, die Amir Timur in seiner Heimatstadt baute; der Name bedeutet „Sitz der Macht und Stärke“. Erhalten ist das hohe Mausoleum seines ältesten und liebsten Sohnes Dschahongir, der 1376 sehr jung starb, mit seiner charakteristischen kegelförmigen Kuppel. In der Nähe fanden Archäologen 1943 eine unterirdische Gruft mit einem Steinsarkophag, den Timur für sich selbst vorbereitet hatte – begraben wurde er jedoch in Samarkand, im Gur-Emir. Daneben liegen die Hazrati-Imam-Moschee und ein schattiger Hof mit jahrhundertealten Platanen." },
    fr: { name: "Dorous Saodat et mausolée de Djakhonguir", desc: "Le tombeau familial qu'Amir Timour fit bâtir dans sa ville natale ; son nom signifie « siège du pouvoir et de la puissance ». Il en subsiste le haut mausolée de son fils aîné et préféré Djakhonguir, mort très jeune en 1376, avec sa coupole conique caractéristique. Tout près, en 1943, les archéologues découvrirent une crypte souterraine abritant un sarcophage de pierre que Timour avait préparé pour lui-même – mais il fut enterré à Samarcande, au Gour-Emir. À côté se trouvent la mosquée Hazrati Imam et une cour ombragée de platanes séculaires." },
    ja: { name: "ドルス・サオダトとジャハンギール廟", desc: "アミール・ティムールが故郷に建てた一族の墓所で、名前は「権力と威厳の座」を意味します。1376年に若くして亡くなった最愛の長男ジャハンギールの高い霊廟が、特徴的な円錐形のドームとともに残っています。1943年、近くで考古学者たちがティムールが自分のために用意した石棺のある地下墓室を発見しましたが、彼はサマルカンドのグル・アミール廟に葬られました。隣にはハズラティ・イマーム・モスクと、樹齢数百年のプラタナスが木陰をつくる中庭があります。" },
    tr: { name: "Dorus Saadet ve Cihangir Türbesi", desc: "Emir Timur'un doğduğu şehirde yaptırdığı aile türbesi; adı “Güç ve Kudret Makamı” demektir. 1376'da çok genç yaşta ölen en büyük ve en sevdiği oğlu Cihangir'in yüksek türbesi, kendine özgü konik kubbesiyle ayakta kalmıştır. 1943'te arkeologlar yakında Timur'un kendisi için hazırladığı taş lahdi bulunan bir yeraltı mezar odası buldu – ama Timur Semerkant'ta, Gur-i Emir'de gömüldü. Yanında Hazreti İmam Camii ve asırlık çınarların gölgelediği bir avlu vardır." },
    ar: { name: "دار السيادة وضريح جهانغير", desc: "المدفن العائلي الذي بناه أمير تيمور في مدينته الأم، ويعني اسمه «مقام السلطة والقوة». بقي منه الضريح العالي لابنه البكر والأحب إليه جهانغير الذي توفي شابًا عام 1376، بقبته المخروطية المميزة. وبالقرب منه اكتشف علماء الآثار عام 1943 سردابًا تحت الأرض فيه تابوت حجري أعدّه تيمور لنفسه – لكنه دُفن في سمرقند في ضريح غور أمير. وبجواره مسجد حضرتي إمام وفناء ظليل بأشجار دلب معمّرة." },
  },
  "kd-chorsu": {
    zh: { name: "沙赫里萨布兹的乔尔苏商业穹顶", desc: "沙赫里萨布兹老市场街交汇处一座15世纪的八角形商业穹顶——“乔尔苏”意为“四个方向”。昔日高大的穹顶下出售布料和帽子；如今这里是手工艺中心，可以看到沙赫里萨布兹的苏扎尼刺绣、花帽和当地工匠的作品。穹顶位于白宫与多鲁特·蒂洛瓦特建筑群之间的步行轴线上，旁边就是热闹的城市巴扎。" },
    ko: { name: "샤흐리사브즈 초르수 상업 돔", desc: "샤흐리사브즈 옛 시장 거리의 교차로에 있는 15세기 팔각형 상업 돔으로, ‘초르수’는 ‘네 방향’이라는 뜻입니다. 옛날에는 높은 돔 아래에서 천과 모자를 팔았고, 지금은 샤흐리사브즈의 수자니 자수, 전통 모자, 지역 장인들의 작품을 볼 수 있는 공예 센터입니다. 악사로이와 도루트 틸로바트 단지 사이 보행로에 있으며, 붐비는 시장 바로 옆입니다." },
    de: { name: "Handelskuppel Chorsu in Schahrisabs", desc: "Eine achteckige Handelskuppel aus dem 15. Jahrhundert an der Kreuzung der alten Marktstraßen von Schahrisabs – „Chorsu“ bedeutet „vier Richtungen“. Unter der hohen Kuppel wurden einst Stoffe und Kopfbedeckungen verkauft; heute beherbergt sie ein Handwerkszentrum mit Susani-Stickereien aus Schahrisabs, Käppchen und Arbeiten örtlicher Kunsthandwerker. Die Kuppel liegt an der Fußgängerachse zwischen Ak-Saray und dem Ensemble Dorut Tilovat, neben dem belebten Stadtbasar." },
    fr: { name: "Coupole marchande Tchorsou de Chakhrisabz", desc: "Une coupole marchande octogonale du XVe siècle au croisement des anciennes rues commerçantes de Chakhrisabz – « Tchorsou » signifie « quatre directions ». On vendait autrefois tissus et coiffes sous sa haute coupole ; elle abrite aujourd'hui un centre d'artisanat où l'on voit les suzanis de Chakhrisabz, des calottes et les œuvres des artisans locaux. La coupole se trouve sur l'axe piéton entre Ak-Saraï et l'ensemble Dorout Tilovat, à côté du bazar animé de la ville." },
    ja: { name: "シャフリサブズのチョルスー・ドーム", desc: "シャフリサブズの古い市場通りの交差点にある15世紀の八角形の交易ドームで、「チョルスー」は「四方」を意味します。かつては高いドームの下で布地や帽子が売られ、今はシャフリサブズのスザニ刺繍、帽子、地元職人の作品が見られる工芸センターになっています。アク・サライとドルト・ティロヴァト建築群を結ぶ歩行者軸上にあり、にぎやかな町のバザールのすぐ隣です。" },
    tr: { name: "Şehrisebz Çarsu Çarşı Kubbesi", desc: "Şehrisebz'in eski çarşı sokaklarının kesiştiği yerde 15. yüzyıldan sekizgen bir çarşı kubbesi – “Çarsu” “dört yön” demektir. Yüksek kubbesinin altında bir zamanlar kumaş ve başlık satılırdı; bugün Şehrisebz suzani işlemelerini, takkeleri ve yerel zanaatkârların eserlerini görebileceğiniz bir el sanatları merkezi vardır. Kubbe Ak Saray ile Dorut Tilavet külliyesi arasındaki yaya aksı üzerinde, kalabalık şehir pazarının yanındadır." },
    ar: { name: "قبة تشورسو التجارية في شهرسبز", desc: "قبة تجارية مثمّنة من القرن الخامس عشر عند تقاطع شوارع السوق القديمة في شهرسبز – و«تشورسو» تعني «الجهات الأربع». كانت تُباع تحت قبتها العالية الأقمشة وأغطية الرأس، وهي اليوم مركز للحرف ترى فيه تطريز السوزاني الشهرسبزي والقلانس وأعمال الحرفيين المحليين. تقع القبة على محور المشاة بين آق سراي ومجمع دار التلاوة، بجوار بازار المدينة المزدحم." },
  },
  "kd-odina": {
    zh: { name: "奥迪纳清真寺", desc: "卡尔希（古称那色波）现存最古老的古迹：昔日城堡中心的一座聚礼清真寺。它的修建与阿米尔·帖木儿1385–1386年远征时的命令有关。清真寺与相邻的经学院和萨尔多巴蓄水池一起构成卡尔希老雷吉斯坦建筑群。自2021年起，这里开设了卡什卡达里亚州镇压受害者纪念馆，展出苏联时期受迫害者的文件、照片和故事。" },
    ko: { name: "오디나 모스크", desc: "고대 나사프, 카르시에 남아 있는 가장 오래된 유적으로, 옛 도시 요새 한가운데 있던 금요 모스크입니다. 그 건립은 아미르 티무르가 1385~1386년 원정 중 내린 명령과 관련이 있습니다. 이웃한 마드라사들, 사르도바 저수 시설과 함께 카르시의 옛 레기스탄 단지를 이룹니다. 2021년부터 소련 시대에 고통받은 사람들의 문서, 사진, 이야기를 전시하는 카시카다리야주 탄압 희생자 기념관이 있습니다." },
    de: { name: "Odina-Moschee", desc: "Das älteste erhaltene Denkmal von Karschi, dem antiken Nasaf: eine Freitagsmoschee im Zentrum der einstigen Stadtfestung. Ihr Bau wird mit einem Befehl Amir Timurs während seines Feldzugs 1385–1386 verbunden. Die Moschee gehört zum alten Registan-Ensemble Karschis, zusammen mit den benachbarten Medresen und der Sardoba-Zisterne. Seit 2021 beherbergt sie das Gedenkmuseum für die Opfer der Repressionen der Region Kaschkadarja mit Dokumenten, Fotos und Geschichten von Menschen, die in Sowjetzeiten litten." },
    fr: { name: "Mosquée Odina", desc: "Le plus ancien monument conservé de Karchi, l'antique Nasaf : une mosquée du vendredi au centre de l'ancienne forteresse. Sa construction est liée à un ordre d'Amir Timour lors de sa campagne de 1385–1386. La mosquée fait partie de l'ancien ensemble du Registan de Karchi, avec les médersas voisines et la citerne sardoba. Depuis 2021, elle abrite le musée mémorial des victimes de la répression de la région de Kachkadaria, avec documents, photos et récits de personnes qui ont souffert à l'époque soviétique." },
    ja: { name: "オディナ・モスク", desc: "古代ナサフ、カルシに現存する最古の建造物で、かつての町の要塞の中心にあった金曜モスクです。その建設は、アミール・ティムールが1385～1386年の遠征中に出した命令と結びつけられています。隣接するメドレセやサルドバ（貯水施設）とともに、カルシの旧レギスタン建築群を構成しています。2021年からは、ソ連時代に苦しんだ人々の文書、写真、物語を展示するカシュカダリヤ州弾圧犠牲者記念博物館になっています。" },
    tr: { name: "Odina Camii", desc: "Eski Nesef, yani Karşi'nin ayakta kalan en eski anıtı: eski şehir kalesinin ortasında bir Cuma camii. İnşası, Emir Timur'un 1385–1386 seferi sırasında verdiği bir emirle ilişkilendirilir. Cami, komşu medreseler ve sardoba sarnıcıyla birlikte Karşi'nin eski Registan külliyesinin parçasıdır. 2021'den beri Sovyet döneminde acı çekenlerin belgelerini, fotoğraflarını ve hikâyelerini sergileyen Kaşkaderya Baskı Kurbanları Anı Müzesi'ne ev sahipliği yapar." },
    ar: { name: "مسجد أدينة", desc: "أقدم معلم باقٍ في قرشي، نسف القديمة: مسجد جامع في وسط قلعة المدينة السابقة. يرتبط بناؤه بأمر من أمير تيمور خلال حملته بين 1385 و1386. والمسجد جزء من مجمع ريغستان القديم في قرشي مع المدارس المجاورة وصهريج «السردوبة». ومنذ 2021 يضم متحف ولاية قشقداريا التذكاري لضحايا القمع، بوثائق وصور وقصص أناس عانوا في الحقبة السوفيتية." },
  },
  "kd-kokgumbazq": {
    zh: { name: "卡尔希的库克·古姆巴兹清真寺", desc: "16世纪末昔班尼王朝阿卜杜拉汗二世时期修建的聚礼清真寺，立面上写有他的名字和伊历999年（1590–1591年）。它因贴着蓝色瓷砖的穹顶而被称为“蓝色穹顶”，穹顶在1898年地震中严重受损，后来得到修复。自1953年起，库克·古姆巴兹再次成为城市的主要聚礼清真寺。这是正在使用的清真寺：请穿着得体，在礼拜时间以外参观。" },
    ko: { name: "카르시의 쿡 굼바즈 모스크", desc: "16세기 말 샤이바니 왕조의 압둘라 칸 2세 때 지은 금요 모스크로, 정면에 그의 이름과 히즈라력 999년(1590~1591)이 새겨져 있습니다. 푸른 타일로 덮인 돔 때문에 ‘푸른 돔’이라 불리며, 이 돔은 1898년 지진으로 크게 손상된 뒤 복원되었습니다. 1953년부터 쿡 굼바즈는 다시 도시의 주요 금요 모스크로 쓰이고 있습니다. 현재 예배하는 모스크이니 단정하게 입고 예배 시간을 피해 방문하세요." },
    de: { name: "Kok-Gumbaz-Moschee in Karschi", desc: "Eine Freitagsmoschee vom Ende des 16. Jahrhunderts, erbaut unter dem Schaibaniden Abdullah Khan II., dessen Name und das Datum 999 n. H. (1590–1591) an der Fassade stehen. „Blaue Kuppel“ heißt sie nach ihrer mit blauen Fliesen verkleideten Kuppel, die beim Erdbeben von 1898 schwer beschädigt und später restauriert wurde. Seit 1953 dient Kok Gumbaz wieder als Hauptfreitagsmoschee der Stadt. Eine aktive Moschee: zurückhaltend kleiden und außerhalb der Gebetszeiten besuchen." },
    fr: { name: "Mosquée Kok Goumbaz de Karchi", desc: "Une mosquée du vendredi de la fin du XVIe siècle, bâtie sous le Chaybanide Abdoullah Khan II, dont le nom et la date 999 de l'Hégire (1590–1591) figurent sur la façade. On l'appelle « coupole bleue » d'après sa coupole revêtue de carreaux bleus, gravement endommagée par le séisme de 1898 puis restaurée. Depuis 1953, Kok Goumbaz est de nouveau la principale mosquée du vendredi de la ville. Mosquée active : tenue correcte et visite en dehors des heures de prière." },
    ja: { name: "カルシのコク・グンバズ・モスク", desc: "16世紀末、シャイバーン朝のアブドゥッラー・ハン2世の時代に建てられた金曜モスクで、正面には彼の名とヒジュラ暦999年（1590～1591年）が記されています。青いタイルで覆われたドームから「青いドーム」と呼ばれ、このドームは1898年の地震で大きく損傷し、のちに修復されました。1953年からコク・グンバズは再び町の主要な金曜モスクとして使われています。現役のモスクなので、控えめな服装で礼拝時間外に訪れてください。" },
    tr: { name: "Karşi'deki Gök Kubbe Camii", desc: "Şeybani hükümdarı II. Abdullah Han döneminde yapılan 16. yüzyıl sonu bir Cuma camii; cephesinde onun adı ve hicri 999 (1590–1591) tarihi yazılıdır. Mavi çinilerle kaplı kubbesi nedeniyle “Mavi Kubbe” denir; kubbe 1898 depreminde ağır hasar gördü ve sonra onarıldı. 1953'ten beri Gök Kubbe yeniden şehrin ana Cuma camiidir. Faal bir camidir: kapalı giyinin ve namaz vakitleri dışında ziyaret edin." },
    ar: { name: "مسجد كوك غومباز في قرشي", desc: "مسجد جامع من أواخر القرن السادس عشر بُني في عهد الشيباني عبد الله خان الثاني، ويظهر اسمه وتاريخ 999 هـ (1590–1591) على الواجهة. يُسمّى «القبة الزرقاء» نسبةً إلى قبته المكسوة ببلاط أزرق، التي تضررت بشدة في زلزال 1898 ثم رُمّمت. ومنذ 1953 عاد كوك غومباز ليكون المسجد الجامع الرئيسي في المدينة. مسجد قائم: ارتدِ ملابس محتشمة وزُره خارج أوقات الصلاة." },
  },
  "kd-bekmir": {
    zh: { name: "别克米尔经学院", desc: "卡尔希历史中心的经学院之一，距奥迪纳清真寺和萨尔多巴蓄水池仅几步之遥。这是一座典型的中亚经学院：入口门楼、角上的古尔达斯塔小塔，以及四周环绕着胡吉拉（学生居住和学习的小室）的方形庭院。雕花木门和砖砌装饰最适合近距离欣赏。它可以与基利奇博伊经学院、阿卜杜拉齐兹·霍贾经学院一起，在一次漫步中游览卡尔希老雷吉斯坦。" },
    ko: { name: "베크미르 마드라사", desc: "카르시 역사 지구의 마드라사 중 하나로, 오디나 모스크와 사르도바 저수 시설에서 몇 걸음 거리에 있습니다. 입구 정문, 모서리의 굴다스타 작은 탑, 학생들이 살며 공부하던 방 후즈라가 둘러싼 정사각형 안뜰을 갖춘 전형적인 중앙아시아 마드라사입니다. 조각된 나무 문과 벽돌 장식은 가까이서 보는 것이 좋습니다. 킬리치보이, 압둘아지즈 호자 마드라사와 함께 카르시 옛 레기스탄을 한 번에 걸으며 둘러볼 수 있습니다." },
    de: { name: "Medrese Bekmir", desc: "Eine der Medresen im historischen Zentrum von Karschi, wenige Schritte von der Odina-Moschee und der Sardoba-Zisterne entfernt. Eine klassische zentralasiatische Medrese: Eingangsportal, Eck-Türmchen (Guldasta) und ein quadratischer Hof mit Hudschras, den Zellen, in denen Studenten wohnten und lernten. Die geschnitzte Holztür und der Ziegeldekor wirken aus der Nähe am besten. Zusammen mit den Medresen Qilichboy und Abdulaziz-Chodscha passt sie in einen einzigen Rundgang über Karschis alten Registan." },
    fr: { name: "Médersa Bekmir", desc: "L'une des médersas du centre historique de Karchi, à quelques pas de la mosquée Odina et de la citerne sardoba. C'est une médersa d'Asie centrale classique : portail d'entrée, tourelles d'angle guldasta et cour carrée bordée de hujras, les cellules où les étudiants vivaient et étudiaient. La porte en bois sculpté et le décor de brique se voient mieux de près. Elle s'intègre dans une même promenade sur l'ancien Registan de Karchi avec les médersas Qilitchboï et Abdoulaziz-Khodja." },
    ja: { name: "ベクミル・メドレセ", desc: "カルシ歴史地区のメドレセのひとつで、オディナ・モスクやサルドバ（貯水施設）から数歩の距離にあります。入口の門、角のグルダスタ（小塔）、学生が暮らし学んだ小部屋フジュラに囲まれた四角い中庭を備えた、典型的な中央アジアのメドレセです。彫刻の施された木の扉とレンガの装飾は近くで見るのがおすすめ。キリチボイ、アブドゥルアジズ・ホジャの両メドレセとあわせて、カルシの旧レギスタンをひと続きで散策できます。" },
    tr: { name: "Bekmir Medresesi", desc: "Karşi'nin tarihi merkezindeki medreselerden biri; Odina Camii'ne ve sardoba sarnıcına birkaç adım mesafededir. Klasik bir Orta Asya medresesidir: giriş taç kapısı, köşe guldeste kuleleri ve öğrencilerin yaşayıp okuduğu hücrelerle çevrili kare avlu. Oyma ahşap kapı ve tuğla süslemeler en iyi yakından görülür. Kılıçboy ve Abdülaziz Hoca medreseleriyle birlikte Karşi'nin eski Registanı'nda tek bir yürüyüşe sığar." },
    ar: { name: "مدرسة بيكمير", desc: "إحدى مدارس المركز التاريخي في قرشي، على بعد خطوات من مسجد أدينة وصهريج السردوبة. هي مدرسة كلاسيكية من آسيا الوسطى: بوابة دخول، وأبراج ركنية صغيرة «غولدستة»، وفناء مربع تحيط به الحجرات التي كان الطلاب يقيمون ويدرسون فيها. يحسن تأمل الباب الخشبي المنحوت والزخارف الآجرية عن قرب. ويمكن زيارتها مع مدرستي قيليتشبوي وعبد العزيز خوجة في جولة واحدة حول ريغستان قرشي القديم." },
  },
  "kd-qilichboy": {
    zh: { name: "基利奇博伊经学院", desc: "卡尔希老城中心的一座经学院，属于奥迪纳清真寺周围的历史建筑群。它的双层砖砌立面带有门楼和一排排拱形小室壁龛，是布哈拉流派的典型风格——这一流派塑造了布哈拉汗国主要城市之一卡尔希的建筑。它位于奥迪纳清真寺和阿卜杜拉齐兹·霍贾经学院之间的一条短步行街上，顺路就能看到。庭院并非总是开放，请在现场询问。" },
    ko: { name: "킬리치보이 마드라사", desc: "카르시 옛 중심가의 마드라사로, 오디나 모스크 주변 역사 단지의 일부입니다. 정문과 아치형 방 벽감이 줄지어 있는 2층 벽돌 정면은 부하라 학파의 전형으로, 이 양식은 부하라 칸국의 주요 도시 중 하나였던 카르시의 건축을 이루었습니다. 오디나 모스크와 압둘아지즈 호자 마드라사 사이의 짧은 보행로에 있어 가는 길에 쉽게 볼 수 있습니다. 안뜰은 항상 열려 있지 않으니 현장에서 물어보세요." },
    de: { name: "Medrese Qilichboy", desc: "Eine Medrese im alten Zentrum von Karschi, Teil des historischen Ensembles rund um die Odina-Moschee. Ihre zweigeschossige Ziegelfassade mit Portal und Reihen gewölbter Zellennischen ist typisch für die Buchara-Schule, die die Architektur von Karschi prägte, einer der Hauptstädte des Emirats Buchara. Sie liegt an einer kurzen Fußgängerstraße zwischen der Odina-Moschee und der Medrese Abdulaziz-Chodscha und ist daher unterwegs leicht zu sehen. Der Hof ist nicht immer offen – vor Ort fragen." },
    fr: { name: "Médersa Qilitchboï", desc: "Une médersa du vieux centre de Karchi, faisant partie de l'ensemble historique autour de la mosquée Odina. Sa façade de brique à deux niveaux, avec portail et rangées de niches de cellules en arc, est typique de l'école de Boukhara, qui a façonné l'architecture de Karchi, l'une des principales villes de l'émirat de Boukhara. Elle se trouve sur une courte rue piétonne entre la mosquée Odina et la médersa Abdoulaziz-Khodja, on la voit donc facilement en chemin. La cour n'est pas toujours ouverte – renseignez-vous sur place." },
    ja: { name: "キリチボイ・メドレセ", desc: "カルシ旧市街のメドレセで、オディナ・モスク周辺の歴史的建築群の一部です。門とアーチ形の小部屋の壁龕が並ぶ2層のレンガのファサードはブハラ派の典型で、この様式はブハラ・アミール国の主要都市のひとつであったカルシの建築をかたちづくりました。オディナ・モスクとアブドゥルアジズ・ホジャ・メドレセを結ぶ短い歩行者通りにあり、途中で気軽に見られます。中庭はいつも開いているわけではないので、現地で尋ねてください。" },
    tr: { name: "Kılıçboy Medresesi", desc: "Karşi'nin eski merkezinde, Odina Camii çevresindeki tarihi külliyenin parçası olan bir medrese. Taç kapılı ve sıra sıra kemerli hücre nişleri olan iki katlı tuğla cephesi, Buhara Emirliği'nin başlıca şehirlerinden Karşi'nin mimarisini şekillendiren Buhara ekolünün tipik örneğidir. Odina Camii ile Abdülaziz Hoca Medresesi arasındaki kısa bir yaya sokağında durur, yol üstünde kolayca görülür. Avlu her zaman açık değildir – yerinde sorun." },
    ar: { name: "مدرسة قيليتشبوي", desc: "مدرسة في وسط قرشي القديم، جزء من المجمع التاريخي حول مسجد أدينة. واجهتها الآجرية ذات الطابقين مع بوابة وصفوف من محاريب الحجرات المقوسة نموذجية للمدرسة البخارية التي شكّلت عمارة قرشي، إحدى المدن الرئيسية في إمارة بخارى. تقع في شارع مشاة قصير بين مسجد أدينة ومدرسة عبد العزيز خوجة، فيسهل رؤيتها في الطريق. الفناء ليس مفتوحًا دائمًا – اسأل في المكان." },
  },
  "kd-abdulaziz": {
    zh: { name: "阿卜杜拉齐兹·霍贾经学院", desc: "卡尔希老城的一座经学院，位于奥迪纳清真寺旁历史建筑群的北缘。朴素的门楼后面是带有小室回廊和伊万雕花木柱的庭院，内部是砖砌拱顶的穹顶房间。它与别克米尔、基利奇博伊经学院一起，构成了卡什卡达里亚罕见的、在20世纪幸存下来的一组学校建筑。从容地走遍所有经学院、奥迪纳清真寺和萨尔多巴大约需要一小时。" },
    ko: { name: "압둘아지즈 호자 마드라사", desc: "오디나 모스크 옆 역사 단지의 북쪽 끝에 있는 옛 카르시의 마드라사입니다. 소박한 정문 뒤에는 방들이 늘어선 회랑과 이완의 조각된 나무 기둥이 있는 안뜰이 있고, 안쪽에는 벽돌 볼트로 덮인 돔형 방들이 있습니다. 베크미르, 킬리치보이 마드라사와 함께 카시카다리야에서는 드물게 20세기를 견뎌 낸 학교 건물군을 이룹니다. 모든 마드라사와 오디나 모스크, 사르도바를 여유롭게 둘러보는 데 약 1시간이 걸립니다." },
    de: { name: "Medrese Abdulaziz-Chodscha", desc: "Eine Medrese des alten Karschi am Nordrand des historischen Ensembles bei der Odina-Moschee. Hinter einem schlichten Portal liegt ein Hof mit Zellengalerien und den geschnitzten Holzsäulen eines Iwans, im Inneren Kuppelräume mit Ziegelgewölben. Zusammen mit den Medresen Bekmir und Qilichboy bildet sie eine für Kaschkadarja seltene Gruppe von Schulbauten, die das 20. Jahrhundert überstanden haben. Ein gemütlicher Rundgang über alle Medresen, die Odina-Moschee und die Sardoba dauert etwa eine Stunde." },
    fr: { name: "Médersa Abdoulaziz-Khodja", desc: "Une médersa de l'ancien Karchi, au bord nord de l'ensemble historique près de la mosquée Odina. Derrière un portail modeste s'ouvre une cour avec des galeries de cellules et les colonnes de bois sculpté d'un iwan ; à l'intérieur, des salles à coupole aux voûtes de brique. Avec les médersas Bekmir et Qilitchboï, elle forme un groupe d'édifices scolaires ayant survécu au XXe siècle, chose rare au Kachkadaria. Une promenade tranquille entre toutes les médersas, la mosquée Odina et la sardoba prend environ une heure." },
    ja: { name: "アブドゥルアジズ・ホジャ・メドレセ", desc: "オディナ・モスクそばの歴史的建築群の北端にある、古いカルシのメドレセです。簡素な門の奥には、小部屋の回廊とイーワーンの彫刻入り木柱のある中庭があり、内部にはレンガのヴォールトを持つドーム天井の部屋があります。ベクミル、キリチボイの両メドレセとともに、カシュカダリヤでは珍しく20世紀を生き延びた学校建築群をなしています。すべてのメドレセとオディナ・モスク、サルドバをゆっくり歩いて回ると約1時間です。" },
    tr: { name: "Abdülaziz Hoca Medresesi", desc: "Odina Camii yanındaki tarihi külliyenin kuzey ucunda, eski Karşi'nin bir medresesi. Sade bir taç kapının ardında hücre revakları ve eyvanın oyma ahşap sütunlarıyla bir avlu, içeride tuğla tonozlu kubbeli odalar bulunur. Bekmir ve Kılıçboy medreseleriyle birlikte, Kaşkaderya'da 20. yüzyılı atlatabilmiş nadir okul yapıları grubunu oluşturur. Tüm medreseleri, Odina Camii'ni ve sardobayı rahatça gezmek yaklaşık bir saat sürer." },
    ar: { name: "مدرسة عبد العزيز خوجة", desc: "مدرسة من قرشي القديم على الطرف الشمالي للمجمع التاريخي قرب مسجد أدينة. خلف بوابة متواضعة فناء بأروقة من الحجرات وأعمدة خشبية منحوتة لإيوان، وفي الداخل غرف مقببة بأقبية آجرية. وتشكّل مع مدرستي بيكمير وقيليتشبوي مجموعة من المباني التعليمية نادرًا ما صمد مثلها في قشقداريا حتى نهاية القرن العشرين. وتستغرق جولة متأنية بين المدارس كلها ومسجد أدينة والسردوبة نحو ساعة." },
  },
  "kd-sardoba": {
    zh: { name: "卡尔希萨尔多巴", desc: "萨尔多巴是一种古老的带穹顶的蓄水池，对这片炎热干旱土地上的城镇和商路至关重要。深深的水池从渠道或融雪中蓄水，穹顶和厚厚的砖墙使水保持凉爽，并防止灰尘和蒸发。卡尔希的萨尔多巴位于历史中心，紧邻奥迪纳清真寺和别克米尔经学院。低矮基座上的半球形穹顶是古城那色波的经典景观之一。" },
    ko: { name: "카르시 사르도바", desc: "사르도바는 돔을 얹은 옛 저수 시설로, 덥고 건조한 이 땅의 도시와 대상로에 꼭 필요했습니다. 깊은 저수조는 수로나 눈 녹은 물로 채워졌고, 돔과 두꺼운 벽돌 벽이 물을 시원하게 지키며 먼지와 증발을 막았습니다. 카르시 사르도바는 역사 지구에서 오디나 모스크와 베크미르 마드라사 바로 옆에 있습니다. 낮은 기단 위의 반구형 돔은 옛 나사프의 대표적인 풍경 중 하나입니다." },
    de: { name: "Sardoba von Karschi", desc: "Eine Sardoba ist eine alte überkuppelte Wasserzisterne, unentbehrlich für Städte und Karawanenwege in diesem heißen, trockenen Land. Das tiefe Becken wurde aus Kanälen oder mit Schmelzwasser gefüllt, und Kuppel und dicke Ziegelmauern hielten das Wasser kühl und schützten es vor Staub und Verdunstung. Die Sardoba von Karschi steht im historischen Zentrum neben der Odina-Moschee und der Medrese Bekmir. Ihre halbkugelförmige Kuppel auf niedrigem Sockel ist einer der klassischen Anblicke des alten Nasaf." },
    fr: { name: "Sardoba de Karchi", desc: "Une sardoba est une ancienne citerne à coupole, indispensable aux villes et aux routes caravanières de cette terre chaude et sèche. Le profond réservoir était rempli par les canaux ou l'eau de fonte des neiges, et la coupole et les épais murs de brique gardaient l'eau fraîche, à l'abri de la poussière et de l'évaporation. La sardoba de Karchi se trouve dans le centre historique, à côté de la mosquée Odina et de la médersa Bekmir. Sa coupole hémisphérique sur une base basse est l'une des images classiques de l'antique Nasaf." },
    ja: { name: "カルシのサルドバ", desc: "サルドバとはドームを載せた古い貯水施設で、暑く乾いたこの土地の町や隊商路に欠かせないものでした。深い貯水槽は用水路や雪解け水で満たされ、ドームと厚いレンガの壁が水を冷たく保ち、ほこりや蒸発から守りました。カルシのサルドバは歴史地区にあり、オディナ・モスクとベクミル・メドレセのすぐ隣です。低い基壇の上の半球形のドームは、古都ナサフを代表する景観のひとつです。" },
    tr: { name: "Karşi Sardobası", desc: "Sardoba, bu sıcak ve kurak toprakta şehirler ve kervan yolları için hayati olan, kubbeli eski bir su sarnıcıdır. Derin hazne kanallardan ya da kar suyuyla doldurulur; kubbe ve kalın tuğla duvarlar suyu serin tutar, tozdan ve buharlaşmadan korurdu. Karşi sardobası tarihi merkezde, Odina Camii ve Bekmir Medresesi'nin yanındadır. Alçak bir kaide üzerindeki yarım küre kubbesi, eski Nesef'in klasik manzaralarından biridir." },
    ar: { name: "سردوبة قرشي", desc: "السردوبة صهريج ماء قديم مقبب، كان لا غنى عنه للمدن وطرق القوافل في هذه الأرض الحارة الجافة. كان الحوض العميق يُملأ من القنوات أو بمياه ذوبان الثلوج، وكانت القبة والجدران الآجرية السميكة تحفظ الماء باردًا وتحميه من الغبار والتبخر. تقع سردوبة قرشي في المركز التاريخي بجوار مسجد أدينة ومدرسة بيكمير. وقبتها نصف الكروية على قاعدة منخفضة من المشاهد الكلاسيكية لنسف القديمة." },
  },
  "kd-bridge": {
    zh: { name: "卡尔希古桥", desc: "卡尔希北部横跨卡什卡达里亚河的砖砌拱桥，建于1583年昔班尼王朝时期。它是整个中亚现存最古老、规模最大的同类桥梁之一：几个巨大的桥拱架在坚固的桥墩上，几个世纪以来经受住了春季洪水。当地人称它为阿米尔·帖木儿桥，在俄国时期它被称为尼古拉耶夫桥。如今它供行人通行——是傍晚在河上散步看日落的好地方。" },
    ko: { name: "카르시 다리", desc: "카르시 북쪽 카시카다리야강을 가로지르는 벽돌 아치교로, 1583년 샤이바니 왕조 때 세워졌습니다. 중앙아시아 전체에서 현존하는 같은 종류의 다리 중 가장 오래되고 큰 것 가운데 하나로, 튼튼한 교각 위의 거대한 아치 몇 개가 수백 년 동안 봄철 홍수를 견뎌 왔습니다. 현지인들은 아미르 티무르 다리라고 부르며, 러시아 시대에는 니콜라옙스키 다리로 알려졌습니다. 지금은 보행자 전용으로, 강 위에서 해 질 녘 산책을 즐기기 좋습니다." },
    de: { name: "Brücke von Karschi", desc: "Eine gemauerte Bogenbrücke über den Fluss Kaschkadarja im Norden von Karschi, erbaut 1583 unter den Schaibaniden. Sie ist eine der ältesten und größten erhaltenen Brücken ihrer Art in ganz Zentralasien: Mehrere mächtige Bögen auf kräftigen Pfeilern haben jahrhundertelang den Frühjahrshochwassern standgehalten. Einheimische nennen sie Amir-Timur-Brücke, in russischer Zeit hieß sie Nikolaus-Brücke. Heute ist sie für Fußgänger – ein schöner Ort für einen Spaziergang über den Fluss bei Sonnenuntergang." },
    fr: { name: "Pont de Karchi", desc: "Un pont de brique à arches sur la rivière Kachkadaria au nord de Karchi, construit en 1583 sous les Chaybanides. C'est l'un des plus anciens et des plus grands ponts de ce type conservés dans toute l'Asie centrale : plusieurs arches massives sur de robustes piles ont résisté aux crues printanières pendant des siècles. Les habitants l'appellent pont Amir Timour ; à l'époque russe, on le nommait pont Nicolas. Il est aujourd'hui piétonnier – un lieu agréable pour une promenade au-dessus de la rivière au coucher du soleil." },
    ja: { name: "カルシ橋", desc: "カルシ北部でカシュカダリヤ川に架かるレンガ造りのアーチ橋で、1583年にシャイバーン朝のもとで建設されました。中央アジア全体でも現存する同種の橋のなかで最も古く大きいもののひとつで、頑丈な橋脚の上の巨大なアーチがいくつも、何世紀にもわたって春の洪水に耐えてきました。地元ではアミール・ティムール橋と呼ばれ、ロシア時代にはニコラエフスキー橋として知られていました。今は歩行者専用で、夕暮れに川の上を散歩するのにぴったりです。" },
    tr: { name: "Karşi Köprüsü", desc: "Karşi'nin kuzeyinde Kaşkaderya nehri üzerinde, 1583'te Şeybaniler döneminde yapılmış tuğla kemerli bir köprü. Tüm Orta Asya'da türünün ayakta kalan en eski ve en büyük köprülerinden biridir: sağlam ayaklar üzerindeki birkaç devasa kemer yüzyıllardır bahar taşkınlarına dayanmıştır. Yerliler ona Emir Timur Köprüsü der; Rus döneminde Nikolayevski Köprüsü olarak bilinirdi. Bugün yayalara açıktır – gün batımında nehir üzerinde yürüyüş için hoş bir yer." },
    ar: { name: "جسر قرشي", desc: "جسر آجري مقوّس على نهر قشقداريا شمال قرشي، بُني عام 1583 في عهد الشيبانيين. وهو من أقدم وأكبر الجسور الباقية من نوعه في آسيا الوسطى كلها: عدة أقواس ضخمة على ركائز متينة صمدت قرونًا أمام فيضانات الربيع. يسميه السكان جسر أمير تيمور، وكان يُعرف في العهد الروسي بجسر نيقولاي. وهو اليوم للمشاة – مكان لطيف للتنزه فوق النهر عند الغروب." },
  },
  "kd-erkurgan": {
    zh: { name: "叶尔库尔干古城遗址", desc: "那黑沙不（卡尔希在粟特时代的前身）的遗址，位于现代城市西北约10公里的布哈拉公路旁。名字意为“土城堡”。古城分为内城和外城，周围环绕着厚重的城墙；内城呈清晰的五边形，面积约40公顷，几十座土丘下埋藏着住宅和公共建筑。发掘始于1948年，从1970年代起成为系统性考古。这是露天考古遗址：请带上水和帽子。" },
    ko: { name: "예르쿠르간 고대 유적", desc: "카르시의 고대 소그드 시대 전신인 나흐샤브의 유적으로, 현대 도시에서 북서쪽으로 약 10km, 부하라 도로변에 있습니다. 이름은 ‘흙 요새’라는 뜻입니다. 도시는 거대한 성벽에 둘러싸인 내성과 외성으로 나뉘었고, 내성은 약 40헥타르의 뚜렷한 오각형으로 수십 개의 언덕 아래 주거지와 공공건물이 묻혀 있습니다. 발굴은 1948년에 시작되어 1970년대부터 체계적으로 이루어졌습니다. 야외 고고학 유적이니 물과 모자를 챙기세요." },
    de: { name: "Ruinenstätte Jerkurgan", desc: "Die Ruinen von Nachschab, dem antiken sogdischen Vorläufer von Karschi, etwa 10 km nordwestlich der heutigen Stadt an der Straße nach Buchara. Der Name bedeutet „Erdfestung“. Die Stadt bestand aus einem inneren und einem äußeren Teil, umgeben von mächtigen Mauern; die Innenstadt ist ein deutliches Fünfeck von etwa 40 Hektar mit Dutzenden Hügeln, unter denen Wohn- und öffentliche Bauten liegen. Die Ausgrabungen begannen 1948 und wurden in den 1970er-Jahren systematisch. Eine offene archäologische Stätte: Wasser und Hut mitnehmen." },
    fr: { name: "Site antique d'Erkourgan", desc: "Les ruines de Nakhchab, l'ancêtre sogdien de Karchi, à environ 10 km au nord-ouest de la ville moderne, au bord de la route de Boukhara. Le nom signifie « forteresse de terre ». La ville comprenait une partie intérieure et une partie extérieure entourées de murailles massives ; la ville intérieure forme un pentagone net d'environ 40 hectares, avec des dizaines de buttes cachant des bâtiments résidentiels et publics. Les fouilles commencèrent en 1948 et devinrent systématiques dans les années 1970. Site archéologique à ciel ouvert : prévoyez de l'eau et un chapeau." },
    ja: { name: "エルクルガン遺跡", desc: "カルシの前身である古代ソグドの都市ナフシャブの遺跡で、現在の市街から北西へ約10km、ブハラ街道沿いにあります。名前は「土の要塞」を意味します。都市は巨大な城壁に囲まれた内城と外城からなり、内城は約40ヘクタールのはっきりした五角形で、数十の丘の下に住居や公共建築が埋もれています。発掘は1948年に始まり、1970年代から体系的に行われるようになりました。屋外の遺跡なので、水と帽子を持参してください。" },
    tr: { name: "Yerkurgan Antik Kenti", desc: "Karşi'nin eski Soğd dönemindeki öncülü Nahşeb'in kalıntıları; modern şehrin yaklaşık 10 km kuzeybatısında, Buhara yolu kenarındadır. Adı “Toprak Kale” demektir. Şehir, güçlü surlarla çevrili iç ve dış kısımlardan oluşuyordu; iç şehir yaklaşık 40 hektarlık belirgin bir beşgendir ve onlarca höyüğün altında konut ve kamu yapıları gizlidir. Kazılar 1948'de başladı ve 1970'lerde sistemli hale geldi. Açık bir arkeolojik alandır: su ve şapka alın." },
    ar: { name: "موقع يركورغان الأثري", desc: "أطلال نخشب، السلف الصغدي القديم لقرشي، على بعد نحو 10 كم شمال غرب المدينة الحديثة عند طريق بخارى. يعني الاسم «القلعة الترابية». كانت المدينة تتألف من قسم داخلي وآخر خارجي تحيط بهما أسوار ضخمة؛ والمدينة الداخلية خماسية الشكل بوضوح بمساحة نحو 40 هكتارًا، وتخفي عشرات التلال تحتها مباني سكنية وعامة. بدأت الحفريات عام 1948 وصارت منهجية في السبعينيات. موقع أثري مكشوف: احمل ماءً وقبعة." },
  },
  "kd-langarota": {
    zh: { name: "兰加尔·奥塔陵墓与清真寺", desc: "卡马希区山村兰加尔的一处圣地：15世纪苏菲谢赫穆罕默德·萨迪克的陵墓——他是伊什基亚教团备受尊敬的导师——以及一座有彩绘木天花板的古老清真寺。传说谢赫从麦加带来一部《古兰经》和先知的一根头发，在他的骆驼卧下的地方定居下来——至今人们仍会指给你看一块骆驼形状的石头。“兰加尔”意为“锚”或“庇护所”。山路风景优美；请穿着得体，女士应包头巾。" },
    ko: { name: "랑가르 오타 영묘와 모스크", desc: "카마시 지구 산골 마을 랑가르에 있는 성지로, 이시키야 교단의 존경받는 스승이었던 수피 셰이흐 무함마드 사디크의 15세기 영묘와, 채색된 나무 천장이 있는 오래된 모스크가 있습니다. 전설에 따르면 셰이흐는 쿠란과 예언자의 머리카락 한 올을 가지고 메카에서 와서 낙타가 누운 자리에 정착했다고 하며, 지금도 낙타 모양의 돌을 보여 줍니다. ‘랑가르’는 ‘닻’ 또는 ‘피난처’라는 뜻입니다. 산길 경치가 아름답습니다. 단정하게 입고 여성은 머리를 가리세요." },
    de: { name: "Mausoleum und Moschee Langar Ota", desc: "Ein Heiligtum im Bergdorf Langar im Bezirk Kamaschi: das Mausoleum des Sufi-Scheichs Muhammad Sadiq aus dem 15. Jahrhundert, eines verehrten Meisters der Ischqiya-Bruderschaft, und eine alte Moschee mit bemalter Holzdecke. Der Legende nach kam der Scheich mit einem Koran und einem Haar des Propheten aus Mekka und ließ sich dort nieder, wo sich sein Kamel niederlegte – ein kamelförmiger Stein wird noch heute gezeigt. „Langar“ bedeutet „Anker“ oder „Zuflucht“. Die Bergstraße ist landschaftlich schön; zurückhaltend kleiden, Frauen bedecken das Haar." },
    fr: { name: "Mausolée et mosquée Langar Ota", desc: "Un sanctuaire dans le village de montagne de Langar, district de Kamachi : le mausolée du XVe siècle du cheikh soufi Muhammad Sadiq, maître vénéré de la confrérie Ichqiya, et une vieille mosquée au plafond de bois peint. La légende dit que le cheikh vint de La Mecque avec un Coran et un cheveu du Prophète et s'établit là où son chameau se coucha – on montre encore une pierre en forme de chameau. « Langar » signifie « ancre » ou « refuge ». La route de montagne est pittoresque ; tenue correcte, cheveux couverts pour les femmes." },
    ja: { name: "ランガル・オタ廟とモスク", desc: "カマシ地区の山村ランガルにある聖地で、イシュキーヤ教団の尊敬された師であるスーフィーのシェイフ、ムハンマド・サディクの15世紀の霊廟と、彩色された木の天井を持つ古いモスクがあります。伝説によると、シェイフはコーランと預言者の髪の毛を携えてメッカからやって来て、ラクダが伏した場所に住みついたといい、今もラクダの形をした石が示されます。「ランガル」は「錨」または「避難所」を意味します。山道の景色は見事です。控えめな服装で、女性は髪を覆ってください。" },
    tr: { name: "Langar Ata Türbesi ve Camii", desc: "Kamaşi ilçesindeki dağ köyü Langar'da bir ziyaretgâh: İşkıyye tarikatının saygın mürşidi Sufi şeyh Muhammed Sadık'ın 15. yüzyıldan türbesi ve boyalı ahşap tavanlı eski bir cami. Rivayete göre şeyh Mekke'den bir Kur'an ve Peygamber'in bir kılıyla geldi ve devesinin çöktüğü yere yerleşti – deve biçimli bir taş hâlâ gösterilir. “Langar” “çapa” ya da “sığınak” demektir. Dağ yolu manzaralıdır; kapalı giyinin, kadınlar başını örtsün." },
    ar: { name: "ضريح ومسجد لنغر أتا", desc: "مزار في قرية لنغر الجبلية بمقاطعة كماشي: ضريح الشيخ الصوفي محمد صادق من القرن الخامس عشر، وهو شيخ مُبجَّل من الطريقة العشقية، ومسجد قديم بسقف خشبي ملوّن. تقول الأسطورة إن الشيخ جاء من مكة حاملًا مصحفًا وشعرة من شعر النبي، واستقر حيث برك جمله – ولا يزال يُعرض حجر على شكل جمل. و«لنغر» تعني «المرساة» أو «الملجأ». الطريق الجبلي خلاب؛ ارتدِ ملابس محتشمة، وعلى النساء تغطية الشعر." },
  },
  "kd-miraki": {
    zh: { name: "米拉基", desc: "距沙赫里萨布兹16公里、位于吉萨尔山脚下阿克苏河谷的山区度假村。米拉基以气候疗养地和疗养院、夏日的凉爽和果园，以及河边架在水上的塔普昌平台休闲区而闻名。沿河谷再往上，山间小路通往峡谷和吉萨尔自然保护区边缘，附近还有希索拉克水库。这是在沙赫里萨布兹的炎热之后到山里度过一天的好去处；较长的徒步需要当地向导。" },
    ko: { name: "미라키", desc: "샤흐리사브즈에서 16km 떨어진, 기사르산맥 기슭 악수강 계곡의 산악 휴양 마을입니다. 기후 휴양지와 요양원, 여름의 서늘함과 과수원, 물 위에 놓인 탑찬 평상이 있는 강변 휴식처로 유명합니다. 계곡을 더 올라가면 산길이 협곡과 기사르 자연보호구역 가장자리로 이어지고, 가까이에 히소라크 저수지가 있습니다. 샤흐리사브즈의 더위를 피해 산에서 하루를 보내기 좋은 곳이며, 긴 트레킹에는 현지 가이드가 필요합니다." },
    de: { name: "Miraki", desc: "Ein Bergkurort 16 km von Schahrisabs im Tal des Flusses Aksu am Fuß des Hissargebirges. Miraki ist bekannt für seinen Klimakurort und sein Sanatorium, die Sommerfrische und Obstgärten sowie Erholungsplätze am Fluss mit Tapchan-Liegepodesten über dem Wasser. Weiter talaufwärts führen Bergpfade zu Schluchten und an die Ränder des Hissar-Naturschutzgebiets, und der Hisorak-Stausee liegt in der Nähe. Ein guter Ort für einen Tag in den Bergen nach der Hitze von Schahrisabs; für längere Wanderungen braucht man einen örtlichen Führer." },
    fr: { name: "Miraki", desc: "Un village-station de montagne à 16 km de Chakhrisabz, dans la vallée de l'Aksou, au pied de la chaîne du Hissar. Miraki est connu pour sa station climatique et son sanatorium, la fraîcheur estivale et ses vergers, ainsi que pour ses aires de repos au bord de la rivière avec des tapchans posés au-dessus de l'eau. Plus haut dans la vallée, des sentiers mènent aux gorges et aux abords de la réserve naturelle du Hissar, et le réservoir de Hisorak est tout proche. Un bon endroit pour passer une journée en montagne après la chaleur de Chakhrisabz ; pour les randonnées plus longues, il faut un guide local." },
    ja: { name: "ミラキ", desc: "シャフリサブズから16km、ギッサール山脈のふもとのアクス川の谷にある山の保養村です。気候療養地とサナトリウム、夏の涼しさと果樹園、そして水の上に置かれたタプチャン（縁台）のある川辺の憩いの場で知られています。谷をさらに上ると山道が峡谷やギッサール自然保護区の縁へと続き、近くにはヒソラク貯水池があります。シャフリサブズの暑さのあとに山で一日を過ごすのに最適で、長めのハイキングには地元のガイドが必要です。" },
    tr: { name: "Miraki", desc: "Şehrisebz'e 16 km uzaklıkta, Hisar sıradağlarının eteğinde Aksu nehri vadisinde bir dağ tatil köyü. Miraki, iklim tedavi merkezi ve sanatoryumu, yaz serinliği ve meyve bahçeleri, suyun üzerine kurulu tapçan sedirleriyle nehir kenarı dinlenme yerleriyle bilinir. Vadinin yukarısında dağ patikaları kanyonlara ve Hisar Tabiat Koruma Alanı'nın kenarlarına uzanır; Hisorak barajı da yakındır. Şehrisebz sıcağından sonra dağlarda bir gün geçirmek için güzel bir yer; uzun yürüyüşler için yerel rehber gerekir." },
    ar: { name: "ميراكي", desc: "قرية منتجع جبلي على بعد 16 كم من شهرسبز في وادي نهر آقسو عند سفح سلسلة حصار. تشتهر ميراكي بمنتجعها المناخي ومصحّتها، وبرودة صيفها وبساتينها، وأماكن الاستراحة على ضفة النهر بمنصات «تابتشان» فوق الماء. وأعلى الوادي تقود مسارات جبلية إلى الخوانق وأطراف محمية حصار الطبيعية، وخزان حصاراك قريب. مكان جيد لقضاء يوم في الجبال بعد حر شهرسبز؛ وللرحلات الطويلة تحتاج إلى مرشد محلي." },
  },
  "kd-kitab": {
    zh: { name: "基塔布地质保护区", desc: "位于泽拉夫尚山脉西南支脉、海拔1300至2650米之间的保护区，保护着独特的地质剖面。在岩层中可以看到古代海洋动物和植物的化石——那是数亿年前曾拍打这里的海洋留下的痕迹。津济尔班峡谷的剖面是泥盆纪一个界线的国际参照点，吸引着世界各地的地质学家。途中会经过基塔布山口，可以俯瞰卡什卡达里亚河谷。参观需与保护区管理处预约。" },
    ko: { name: "키타브 지질 보호구역", desc: "제라프샨산맥 남서쪽 지맥, 해발 1,300~2,650m에 있는 보호구역으로, 독특한 지질 단면을 보호합니다. 암석층에서는 수억 년 전 이곳에 출렁이던 바다의 흔적인 고대 해양 동식물의 화석을 볼 수 있습니다. 진질반 협곡의 단면은 데본기 경계 중 하나의 국제 기준점으로, 전 세계 지질학자들이 찾아옵니다. 가는 길에 카시카다리야 계곡이 내려다보이는 키타브 고개가 있습니다. 방문은 보호구역 관리소와 미리 조율해야 합니다." },
    de: { name: "Geologisches Schutzgebiet Kitab", desc: "Ein Schutzgebiet an den südwestlichen Ausläufern des Serawschangebirges zwischen 1.300 und 2.650 Metern, das einzigartige geologische Profile bewahrt. In den Gesteinsschichten sind Fossilien urzeitlicher Meerestiere und -pflanzen zu sehen – Spuren eines Meeres, das hier vor Hunderten Millionen Jahren lag. Das Profil in der Zinzilban-Schlucht ist ein internationaler Referenzpunkt für eine der Grenzen des Devons und zieht Geologen aus aller Welt an. Unterwegs liegt der Kitab-Pass mit Blick über das Kaschkadarja-Tal. Besuche werden mit der Verwaltung des Schutzgebiets vereinbart." },
    fr: { name: "Réserve géologique de Kitab", desc: "Une réserve sur les contreforts sud-ouest de la chaîne du Zeravchan, entre 1 300 et 2 650 mètres, qui protège des coupes géologiques uniques. On voit dans les couches rocheuses des fossiles d'animaux et de plantes marins anciens – traces d'une mer qui baignait ces lieux il y a des centaines de millions d'années. La coupe de la gorge de Zinzilban est une référence internationale pour l'une des limites du Dévonien et attire des géologues du monde entier. En chemin se trouve le col de Kitab, avec vue sur la vallée de la Kachkadaria. Les visites s'organisent avec l'administration de la réserve." },
    ja: { name: "キタブ地質保護区", desc: "ゼラフシャン山脈の南西の支脈、標高1300～2650mにある保護区で、独特の地質断面を保護しています。岩の層には古代の海の動物や植物の化石が見られ、数億年前にこの地に打ち寄せていた海の痕跡です。ジンジルバン峡谷の断面はデボン紀の境界のひとつの国際的な基準点で、世界中の地質学者が訪れます。途中にはカシュカダリヤの谷を見渡すキタブ峠があります。見学は保護区の管理事務所と事前に調整が必要です。" },
    tr: { name: "Kitab Jeoloji Koruma Alanı", desc: "Zerefşan sıradağlarının güneybatı uzantılarında, 1.300 ile 2.650 metre arasında eşsiz jeolojik kesitleri koruyan bir alan. Kaya katmanlarında eski deniz hayvanlarının ve bitkilerinin fosilleri görülür – yüz milyonlarca yıl önce burayı yalayan bir denizin izleri. Zinzilban kanyonundaki kesit, Devoniyen döneminin sınırlarından biri için uluslararası bir referans noktasıdır ve dünyanın dört bir yanından jeologları çeker. Yolda Kaşkaderya vadisine bakan Kitab geçidi vardır. Ziyaretler koruma alanı yönetimiyle ayarlanır." },
    ar: { name: "محمية كتاب الجيولوجية", desc: "محمية على المنحدرات الجنوبية الغربية لسلسلة زرافشان بين 1300 و2650 مترًا، تحمي مقاطع جيولوجية فريدة. تُرى في طبقات الصخر أحافير حيوانات ونباتات بحرية قديمة – آثار بحر كان يغمر هذا المكان قبل مئات ملايين السنين. ويُعد المقطع في خانق زنزلبان مرجعًا دوليًا لأحد حدود العصر الديفوني، ويجذب علماء الجيولوجيا من أنحاء العالم. وفي الطريق ممر كتاب المطل على وادي قشقداريا. تُرتب الزيارات مع إدارة المحمية." },
  },
  "kd-maidanak": {
    zh: { name: "麦达纳克天文台", desc: "1970年在沙赫里萨布兹以南约45公里的麦达纳克高原上建立的高山天文台。选址于此是因为罕见的天文气候：干燥稳定的空气和众多晴朗的夜晚，使它成为欧亚大陆最好的观测点之一。如今它隶属于乌兹别克斯坦科学院兀鲁伯天文研究所，并设有国际项目的望远镜。道路为山路；参观和夜间观测须提前预约。" },
    ko: { name: "마이다나크 천문대", desc: "1970년 샤흐리사브즈에서 남쪽으로 약 45km 떨어진 마이다나크 고원에 세워진 고산 천문대입니다. 건조하고 안정된 대기와 많은 맑은 밤이라는 드문 천문 기후 덕분에 이곳이 선택되었으며, 유라시아 최고의 관측지 중 하나입니다. 현재 우즈베키스탄 과학아카데미 울루그베크 천문연구소에 속해 있으며 국제 프로젝트의 망원경들이 있습니다. 산길이며, 방문과 야간 관측은 사전 예약으로만 가능합니다." },
    de: { name: "Observatorium Maidanak", desc: "Ein Hochgebirgsobservatorium, 1970 auf dem Maidanak-Plateau etwa 45 km südlich von Schahrisabs gegründet. Der Ort wurde wegen seines seltenen Astroklimas gewählt: Trockene, ruhige Luft und viele klare Nächte machen ihn zu einem der besten Beobachtungsstandorte Eurasiens. Heute gehört es zum Ulugh-Beg-Institut für Astronomie der Usbekischen Akademie der Wissenschaften und beherbergt Teleskope internationaler Projekte. Die Straße ist bergig; Besuche und nächtliche Beobachtungen nur nach vorheriger Absprache." },
    fr: { name: "Observatoire de Maïdanak", desc: "Un observatoire astronomique de haute altitude fondé en 1970 sur le plateau de Maïdanak, à environ 45 km au sud de Chakhrisabz. Le site fut choisi pour son astroclimat rare : un air sec et stable et de nombreuses nuits claires en font l'un des meilleurs sites d'observation d'Eurasie. Il appartient aujourd'hui à l'Institut astronomique Ouloug Beg de l'Académie des sciences d'Ouzbékistan et accueille des télescopes de projets internationaux. La route est montagneuse ; visites et observations nocturnes uniquement sur rendez-vous." },
    ja: { name: "マイダナク天文台", desc: "1970年、シャフリサブズの南約45kmのマイダナク高原に設立された高山天文台です。乾燥して安定した大気と晴れた夜の多さという珍しい天文気候から選ばれ、ユーラシア有数の観測地となっています。現在はウズベキスタン科学アカデミーのウルグベク天文学研究所に属し、国際プロジェクトの望遠鏡が設置されています。道は山道で、見学や夜間観測は事前予約制です。" },
    tr: { name: "Maydanak Gözlemevi", desc: "1970'te Şehrisebz'in yaklaşık 45 km güneyindeki Maydanak platosunda kurulan yüksek irtifa gözlemevi. Yer, nadir astro-iklimi nedeniyle seçildi: kuru ve durgun hava ile çok sayıda açık gece onu Avrasya'nın en iyi gözlem noktalarından biri yapar. Bugün Özbekistan Bilimler Akademisi Uluğ Bey Astronomi Enstitüsü'ne bağlıdır ve uluslararası projelerin teleskoplarına ev sahipliği yapar. Yol dağlıktır; ziyaretler ve gece gözlemleri yalnızca önceden ayarlanarak yapılır." },
    ar: { name: "مرصد مايدانك", desc: "مرصد فلكي في المرتفعات أُسس عام 1970 على هضبة مايدانك على بعد نحو 45 كم جنوب شهرسبز. اختير الموقع لمناخه الفلكي النادر: هواء جاف ومستقر وليالٍ صافية كثيرة تجعله من أفضل مواقع الرصد في أوراسيا. ويتبع اليوم معهد أولوغ بيك الفلكي التابع لأكاديمية العلوم الأوزبكية، ويضم تلسكوبات لمشاريع دولية. الطريق جبلي؛ والزيارات والرصد الليلي بموعد مسبق فقط." },
  },
  "kd-amankutan": {
    zh: { name: "阿曼库坦与塔赫塔卡拉恰山口", desc: "撒马尔罕通往沙赫里萨布兹、翻越塔赫塔卡拉恰山口的公路上一处长满刺柏林的山谷，位于撒马尔罕州与卡什卡达里亚州交界。盘山公路沿途可见纹理奇特的悬崖、草甸和卡什卡达里亚河谷，春天山坡开满鲜花。山谷里有阿曼库坦洞穴，这是一处旧石器时代遗址，曾出土石器时代的工具。如今这里有国家公园、野餐区和河边的茶馆。冬季山口可能封闭。" },
    ko: { name: "아만쿠탄과 타흐타카라차 고개", desc: "사마르칸트에서 타흐타카라차 고개를 넘어 샤흐리사브즈로 가는 길에 있는, 향나무 숲이 우거진 산골짜기로 사마르칸트주와 카시카다리야주의 경계에 있습니다. 구불구불한 길을 따라 기묘한 무늬의 절벽, 초원, 카시카다리야 계곡이 펼쳐지고, 봄에는 산비탈이 꽃으로 뒤덮입니다. 계곡에는 석기 시대 도구가 발견된 구석기 유적 아만쿠탄 동굴이 있습니다. 지금은 국립공원과 피크닉 장소, 강가의 찻집이 있습니다. 겨울에는 고개가 폐쇄될 수 있습니다." },
    de: { name: "Amankutan und Tachtakaratscha-Pass", desc: "Ein Bergtal mit Wacholderwäldern an der Straße von Samarkand nach Schahrisabs über den Tachtakaratscha-Pass, an der Grenze der Regionen Samarkand und Kaschkadarja. Die Serpentinenstraße gibt den Blick frei auf Felsen mit seltsamen Mustern, Wiesen und das Kaschkadarja-Tal, im Frühling sind die Hänge voller Blumen. Im Tal liegt die Höhle Amankutan, eine altsteinzeitliche Fundstätte, in der Steinwerkzeuge gefunden wurden. Heute gibt es einen Nationalpark, Picknickplätze und Teehäuser am Fluss. Im Winter kann der Pass gesperrt sein." },
    fr: { name: "Amankoutan et col de Takhtakaratcha", desc: "Une vallée de montagne aux forêts de genévriers sur la route de Samarcande à Chakhrisabz par le col de Takhtakaratcha, à la limite des régions de Samarcande et de Kachkadaria. La route en lacets dévoile des falaises aux motifs étranges, des prairies et la vallée de la Kachkadaria ; au printemps, les pentes se couvrent de fleurs. La vallée abrite la grotte d'Amankoutan, site paléolithique où l'on a trouvé des outils de l'âge de pierre. On y trouve aujourd'hui un parc national, des aires de pique-nique et des maisons de thé au bord de la rivière. Le col peut être fermé en hiver." },
    ja: { name: "アマンクタンとタフタカラチャ峠", desc: "サマルカンドからタフタカラチャ峠を越えてシャフリサブズへ向かう道にある、ネズの森が広がる山の谷で、サマルカンド州とカシュカダリヤ州の境にあります。つづら折りの道からは奇妙な模様の岩壁、草原、カシュカダリヤの谷が見え、春には斜面が花で覆われます。谷には石器時代の道具が見つかった旧石器時代の遺跡、アマンクタン洞窟があります。現在は国立公園やピクニック場、川辺のチャイハナがあります。冬は峠が閉鎖されることがあります。" },
    tr: { name: "Amankutan ve Tahtakaraça Geçidi", desc: "Semerkant'tan Tahtakaraça geçidi üzerinden Şehrisebz'e giden yolda, Semerkant ve Kaşkaderya bölgelerinin sınırında ardıç ormanlarıyla kaplı bir dağ vadisi. Virajlı yol tuhaf desenli kayalıkları, çayırları ve Kaşkaderya vadisini gözler önüne serer; ilkbaharda yamaçlar çiçeklerle kaplanır. Vadide, Taş Devri aletlerinin bulunduğu bir Paleolitik yerleşim olan Amankutan mağarası vardır. Bugün bir milli park, piknik alanları ve nehir kenarında çayhaneler bulunur. Geçit kışın kapanabilir." },
    ar: { name: "أمانكوتان وممر تختاكاراتشا", desc: "وادٍ جبلي بغابات العرعر على الطريق من سمرقند إلى شهرسبز عبر ممر تختاكاراتشا، على حدود ولايتي سمرقند وقشقداريا. يكشف الطريق المتعرج عن منحدرات صخرية بنقوش غريبة ومروج ووادي قشقداريا، وفي الربيع تكتسي السفوح بالأزهار. وفي الوادي كهف أمانكوتان، وهو موقع من العصر الحجري القديم عُثر فيه على أدوات حجرية. وفيه اليوم منتزه وطني وأماكن للنزهات ومقاهٍ للشاي على ضفة النهر. قد يُغلق الممر في الشتاء." },
  },
};
